const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>WordFinder Prototype</title>\n    <style>\n      :root {\n        --bg: #f2efe4;\n        --panel: rgba(255, 252, 245, 0.84);\n        --ink: #1a2a24;\n        --muted: #607066;\n        --accent: #1f7a5c;\n        --accent-2: #d96c3f;\n        --accent-3: #f4c95d;\n        --tile: #fffdf7;\n        --tile-edge: rgba(26, 42, 36, 0.12);\n        --tile-active: #1f7a5c;\n        --tile-found: #274c77;\n        --tile-hint: #f4c95d;\n        --block: #29443a;\n        --danger: #b3432f;\n        --shadow: 0 24px 60px rgba(32, 37, 31, 0.18);\n      }\n\n      * {\n        box-sizing: border-box;\n      }\n\n      body {\n        margin: 0;\n        min-height: 100vh;\n        font-family: \"Avenir Next\", \"Trebuchet MS\", sans-serif;\n        color: var(--ink);\n        background:\n          radial-gradient(circle at top left, rgba(244, 201, 93, 0.45), transparent 25%),\n          radial-gradient(circle at top right, rgba(31, 122, 92, 0.28), transparent 28%),\n          linear-gradient(180deg, #f7f2e5 0%, #ebe2ce 100%);\n      }\n\n      main {\n        width: min(1120px, calc(100% - 32px));\n        margin: 0 auto;\n        padding: 28px 0 48px;\n      }\n\n      .hero {\n        display: grid;\n        gap: 10px;\n        margin-bottom: 22px;\n      }\n\n      .eyebrow {\n        letter-spacing: 0.16em;\n        text-transform: uppercase;\n        color: var(--accent);\n        font-size: 0.78rem;\n        font-weight: 700;\n      }\n\n      .hero-meta {\n        display: flex;\n        flex-wrap: wrap;\n        align-items: center;\n        gap: 10px;\n      }\n\n      .version-chip {\n        display: inline-flex;\n        align-items: center;\n        padding: 6px 10px;\n        border-radius: 999px;\n        background: rgba(26, 42, 36, 0.08);\n        color: var(--ink);\n        font-size: 0.8rem;\n        font-weight: 700;\n      }\n\n      h1 {\n        margin: 0;\n        font-family: Georgia, \"Times New Roman\", serif;\n        font-size: clamp(2.4rem, 6vw, 4.4rem);\n        line-height: 0.94;\n        max-width: 10ch;\n      }\n\n      .subtitle {\n        margin: 0;\n        max-width: 60ch;\n        color: var(--muted);\n        font-size: 1.02rem;\n        line-height: 1.5;\n      }\n\n      .layout {\n        display: grid;\n        gap: 20px;\n        grid-template-columns: minmax(320px, 560px) minmax(260px, 1fr);\n        align-items: start;\n      }\n\n      .panel {\n        background: var(--panel);\n        border: 1px solid rgba(255, 255, 255, 0.55);\n        box-shadow: var(--shadow);\n        backdrop-filter: blur(14px);\n        border-radius: 28px;\n      }\n\n      .game-panel {\n        padding: 18px;\n      }\n\n      .sidebar {\n        padding: 18px;\n        display: grid;\n        gap: 16px;\n      }\n\n      .topline,\n      .controls,\n      .options-row,\n      .progress-metrics,\n      .actions {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 10px;\n      }\n\n      .topline {\n        align-items: center;\n        justify-content: space-between;\n        margin-bottom: 14px;\n      }\n\n      .pill {\n        display: inline-flex;\n        align-items: center;\n        gap: 8px;\n        padding: 8px 12px;\n        border-radius: 999px;\n        background: rgba(31, 122, 92, 0.1);\n        color: var(--accent);\n        font-size: 0.86rem;\n        font-weight: 700;\n      }\n\n      .metric {\n        min-width: 108px;\n        padding: 12px 14px;\n        border-radius: 18px;\n        background: rgba(255, 255, 255, 0.72);\n        border: 1px solid rgba(26, 42, 36, 0.08);\n      }\n\n      .metric-label {\n        display: block;\n        font-size: 0.74rem;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        color: var(--muted);\n        margin-bottom: 6px;\n      }\n\n      .metric-value {\n        font-size: 1.18rem;\n        font-weight: 800;\n      }\n\n      button {\n        border: 0;\n        border-radius: 16px;\n        padding: 12px 16px;\n        font: inherit;\n        font-weight: 700;\n        cursor: pointer;\n        transition: transform 140ms ease, box-shadow 140ms ease, background 140ms ease;\n      }\n\n      button:hover {\n        transform: translateY(-1px);\n      }\n\n      button:focus-visible {\n        outline: 3px solid rgba(31, 122, 92, 0.3);\n        outline-offset: 2px;\n      }\n\n      .primary {\n        background: var(--accent);\n        color: white;\n        box-shadow: 0 14px 24px rgba(31, 122, 92, 0.24);\n      }\n\n      .secondary {\n        background: rgba(39, 76, 119, 0.12);\n        color: #274c77;\n      }\n\n      .field {\n        display: grid;\n        gap: 6px;\n        min-width: 150px;\n      }\n\n      .field label {\n        font-size: 0.74rem;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        color: var(--muted);\n        font-weight: 700;\n      }\n\n      select {\n        appearance: none;\n        border: 1px solid rgba(26, 42, 36, 0.12);\n        border-radius: 16px;\n        padding: 12px 38px 12px 14px;\n        background:\n          linear-gradient(45deg, transparent 50%, var(--accent) 50%) calc(100% - 20px) calc(50% - 2px) / 8px 8px no-repeat,\n          linear-gradient(135deg, var(--accent) 50%, transparent 50%) calc(100% - 14px) calc(50% - 2px) / 8px 8px no-repeat,\n          rgba(255, 255, 255, 0.72);\n        color: var(--ink);\n        font: inherit;\n        font-weight: 700;\n      }\n\n      select:focus-visible {\n        outline: 3px solid rgba(31, 122, 92, 0.3);\n        outline-offset: 2px;\n      }\n\n      .ghost {\n        background: rgba(26, 42, 36, 0.08);\n        color: var(--ink);\n      }\n\n      .warning {\n        background: rgba(217, 108, 63, 0.14);\n        color: var(--accent-2);\n      }\n\n      .board-shell {\n        position: relative;\n        padding: 14px;\n        border-radius: 26px;\n        background: linear-gradient(180deg, rgba(255, 255, 255, 0.8), rgba(242, 239, 228, 0.9));\n        border: 1px solid rgba(26, 42, 36, 0.08);\n      }\n\n      .board {\n        display: grid;\n        gap: 10px;\n        touch-action: none;\n        user-select: none;\n      }\n\n      .tile,\n      .block {\n        aspect-ratio: 1;\n        border-radius: 18px;\n      }\n\n      .tile {\n        position: relative;\n        display: grid;\n        place-items: center;\n        background: var(--tile);\n        border: 1px solid var(--tile-edge);\n        color: var(--ink);\n        font-size: clamp(1.12rem, 3vw, 1.5rem);\n        font-weight: 800;\n        box-shadow: inset 0 -4px 0 rgba(26, 42, 36, 0.03);\n      }\n\n      .tile.active {\n        background: var(--tile-active);\n        color: white;\n      }\n\n      .tile.found {\n        background: var(--tile-found);\n        color: white;\n      }\n\n      .tile.hinted:not(.found):not(.active) {\n        background: color-mix(in srgb, var(--tile) 72%, var(--tile-hint));\n      }\n\n      .tile.invalid {\n        background: var(--danger);\n        color: white;\n        animation: shake 260ms ease;\n      }\n\n      .tile.locked {\n        cursor: default;\n      }\n\n      .tile-index {\n        position: absolute;\n        top: 8px;\n        right: 10px;\n        font-size: 0.68rem;\n        opacity: 0.74;\n      }\n\n      .block {\n        background:\n          linear-gradient(145deg, rgba(255, 255, 255, 0.18), transparent),\n          var(--block);\n        border: 1px solid rgba(255, 255, 255, 0.08);\n      }\n\n      .legend {\n        display: flex;\n        gap: 12px;\n        flex-wrap: wrap;\n        margin-top: 14px;\n        color: var(--muted);\n        font-size: 0.9rem;\n      }\n\n      .legend span {\n        display: inline-flex;\n        align-items: center;\n        gap: 8px;\n      }\n\n      .dot {\n        width: 12px;\n        height: 12px;\n        border-radius: 999px;\n        display: inline-block;\n      }\n\n      .slots {\n        display: grid;\n        gap: 10px;\n      }\n\n      .slot {\n        padding: 12px 14px;\n        border-radius: 18px;\n        background: rgba(255, 255, 255, 0.72);\n        border: 1px solid rgba(26, 42, 36, 0.08);\n      }\n\n      .slot-header {\n        display: flex;\n        justify-content: space-between;\n        gap: 12px;\n        align-items: baseline;\n        margin-bottom: 8px;\n      }\n\n      .slot-title {\n        font-size: 0.82rem;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        color: var(--muted);\n      }\n\n      .slot-value {\n        font-family: Georgia, \"Times New Roman\", serif;\n        font-size: 1.24rem;\n        letter-spacing: 0.2em;\n      }\n\n      .slot.solved {\n        border-color: rgba(39, 76, 119, 0.2);\n        background: rgba(39, 76, 119, 0.1);\n      }\n\n      .message-box {\n        min-height: 76px;\n        padding: 14px 16px;\n        border-radius: 20px;\n        background: rgba(26, 42, 36, 0.05);\n      }\n\n      .message-box strong {\n        display: block;\n        margin-bottom: 6px;\n      }\n\n      .helper {\n        color: var(--muted);\n        line-height: 1.5;\n      }\n\n      .current-path {\n        font-size: 1.18rem;\n        font-weight: 800;\n        letter-spacing: 0.12em;\n      }\n\n      .success-banner {\n        padding: 14px 16px;\n        border-radius: 20px;\n        background: linear-gradient(135deg, rgba(31, 122, 92, 0.16), rgba(244, 201, 93, 0.24));\n        border: 1px solid rgba(31, 122, 92, 0.12);\n      }\n\n      @keyframes shake {\n        0%, 100% { transform: translateX(0); }\n        20% { transform: translateX(-3px); }\n        40% { transform: translateX(4px); }\n        60% { transform: translateX(-2px); }\n        80% { transform: translateX(2px); }\n      }\n\n      @media (max-width: 900px) {\n        .layout {\n          grid-template-columns: 1fr;\n        }\n\n        h1 {\n          max-width: none;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <section class=\"hero\">\n        <div class=\"hero-meta\">\n          <div class=\"eyebrow\">WordFinder Prototype</div>\n          <div class=\"version-chip\" id=\"version-chip\">v00.00.01</div>\n        </div>\n        <h1>Trace hidden words. Use every tile once.</h1>\n        <p class=\"subtitle\">\n          Single-page prototype of the core Wend-style mechanic: drag or tap through adjacent\n          letters, avoid blocked cells, and partition the board into the right set of words.\n        </p>\n      </section>\n\n      <section class=\"layout\">\n        <div class=\"panel game-panel\">\n          <div class=\"topline\">\n            <div class=\"pill\" id=\"mode-pill\">Daily puzzle</div>\n            <div class=\"pill\" id=\"puzzle-pill\">Puzzle 1</div>\n          </div>\n\n          <div class=\"board-shell\">\n            <div class=\"board\" id=\"board\" aria-label=\"Word grid\"></div>\n          </div>\n\n          <div class=\"legend\">\n            <span><i class=\"dot\" style=\"background: var(--tile-active)\"></i> Current path</span>\n            <span><i class=\"dot\" style=\"background: var(--tile-found)\"></i> Solved word</span>\n            <span><i class=\"dot\" style=\"background: var(--tile-hint)\"></i> Hint</span>\n          </div>\n        </div>\n\n        <aside class=\"panel sidebar\">\n          <div class=\"progress-metrics\">\n            <div class=\"metric\">\n              <span class=\"metric-label\">Found</span>\n              <span class=\"metric-value\" id=\"found-count\">0 / 4</span>\n            </div>\n            <div class=\"metric\">\n              <span class=\"metric-label\">Hints</span>\n              <span class=\"metric-value\" id=\"hint-count\">0</span>\n            </div>\n            <div class=\"metric\">\n              <span class=\"metric-label\">Time</span>\n              <span class=\"metric-value\" id=\"timer\">00:00</span>\n            </div>\n          </div>\n\n          <div class=\"controls\">\n            <button class=\"primary\" id=\"daily-btn\">Daily board</button>\n            <button class=\"secondary\" id=\"practice-btn\">New practice board</button>\n          </div>\n\n          <div class=\"options-row\">\n            <div class=\"field\">\n              <label for=\"grid-size\">Grid size</label>\n              <select id=\"grid-size\">\n                <option value=\"4x4\">4 x 4</option>\n                <option value=\"5x5\" selected>5 x 5</option>\n              </select>\n            </div>\n          </div>\n\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"submit-btn\">Submit path</button>\n            <button class=\"ghost\" id=\"undo-btn\">Undo</button>\n            <button class=\"warning\" id=\"hint-btn\">Hint</button>\n            <button class=\"ghost\" id=\"reset-btn\">Reset</button>\n          </div>\n\n          <div class=\"message-box\" id=\"message-box\">\n            <strong>Current path</strong>\n            <div class=\"current-path\" id=\"current-path\">—</div>\n            <div class=\"helper\" id=\"message-text\">\n              Drag through neighboring letters or tap tiles to build a path, then submit it.\n            </div>\n          </div>\n\n          <div class=\"slots\" id=\"slots\"></div>\n\n          <div class=\"success-banner\" id=\"success-banner\" hidden>\n            <strong>Board solved.</strong>\n            <div id=\"success-text\"></div>\n          </div>\n        </aside>\n      </section>\n    </main>\n\n    <script>\n      const APP_VERSION = \"v00.00.01\";\n\n      document.title = `WordFinder Prototype ${APP_VERSION}`;\n      document.getElementById(\"version-chip\").textContent = APP_VERSION;\n\n      const puzzleSeeds = [\n        {\n          id: \"pocket-1\",\n          name: \"Pocket Grid\",\n          rows: 4,\n          cols: 4,\n          words: [\n            { text: \"MOON\", path: [0, 1, 2, 3] },\n            { text: \"TIDE\", path: [4, 5, 6, 7] },\n            { text: \"STAR\", path: [8, 9, 10, 11] },\n            { text: \"WAVE\", path: [12, 13, 14, 15] },\n          ],\n        },\n        {\n          id: \"pocket-2\",\n          name: \"Mini Circuit\",\n          rows: 4,\n          cols: 4,\n          words: [\n            { text: \"LAMP\", path: [0, 1, 2, 3] },\n            { text: \"FERN\", path: [4, 5, 6, 7] },\n            { text: \"COVE\", path: [8, 9, 10, 11] },\n            { text: \"BARK\", path: [12, 13, 14, 15] },\n          ],\n        },\n        {\n          id: \"garden-1\",\n          name: \"Winding Start\",\n          rows: 5,\n          cols: 5,\n          words: [\n            { text: \"CAT\", path: [0, 1, 2] },\n            { text: \"WIND\", path: [4, 9, 14, 19] },\n            { text: \"RIVER\", path: [24, 23, 22, 21, 20] },\n            { text: \"PLANET\", path: [5, 6, 7, 8, 13, 18] },\n          ],\n        },\n        {\n          id: \"garden-2\",\n          name: \"Practice Loop\",\n          rows: 5,\n          cols: 5,\n          words: [\n            { text: \"SUN\", path: [0, 1, 2] },\n            { text: \"MIST\", path: [4, 9, 14, 19] },\n            { text: \"BRICK\", path: [24, 23, 22, 21, 20] },\n            { text: \"GARDEN\", path: [5, 6, 7, 8, 13, 18] },\n          ],\n        },\n      ];\n\n      const state = {\n        mode: \"daily\",\n        practiceIndex: 1,\n        selectedGridSize: \"5x5\",\n        puzzle: null,\n        activePath: [],\n        foundWords: [],\n        hints: {},\n        invalidTiles: [],\n        message: \"Drag through neighboring letters or tap tiles to build a path, then submit it.\",\n        startTime: Date.now(),\n        timerHandle: null,\n        gestureExtended: false,\n        draggingPointerId: null,\n      };\n\n      const els = {\n        board: document.getElementById(\"board\"),\n        slots: document.getElementById(\"slots\"),\n        modePill: document.getElementById(\"mode-pill\"),\n        puzzlePill: document.getElementById(\"puzzle-pill\"),\n        foundCount: document.getElementById(\"found-count\"),\n        hintCount: document.getElementById(\"hint-count\"),\n        timer: document.getElementById(\"timer\"),\n        currentPath: document.getElementById(\"current-path\"),\n        messageText: document.getElementById(\"message-text\"),\n        successBanner: document.getElementById(\"success-banner\"),\n        successText: document.getElementById(\"success-text\"),\n        dailyBtn: document.getElementById(\"daily-btn\"),\n        practiceBtn: document.getElementById(\"practice-btn\"),\n        submitBtn: document.getElementById(\"submit-btn\"),\n        undoBtn: document.getElementById(\"undo-btn\"),\n        hintBtn: document.getElementById(\"hint-btn\"),\n        resetBtn: document.getElementById(\"reset-btn\"),\n        gridSize: document.getElementById(\"grid-size\"),\n      };\n\n      function hydratePuzzles() {\n        return puzzleSeeds.map((seed) => {\n          const occupied = new Map();\n\n          seed.words.forEach((word, wordIndex) => {\n            if (word.path.length !== word.text.length) {\n              throw new Error(`Path length mismatch in ${seed.id}:${word.text}`);\n            }\n\n            word.path.forEach((cellIndex, letterIndex) => {\n              const next = word.path[letterIndex + 1];\n              if (next !== undefined) {\n                const [r1, c1] = toCoord(cellIndex, seed.cols);\n                const [r2, c2] = toCoord(next, seed.cols);\n                const delta = Math.abs(r1 - r2) + Math.abs(c1 - c2);\n                if (delta !== 1) {\n                  throw new Error(`Non-adjacent step in ${seed.id}:${word.text}`);\n                }\n              }\n\n              if (occupied.has(cellIndex)) {\n                throw new Error(`Overlapping tile in ${seed.id} at ${cellIndex}`);\n              }\n\n              occupied.set(cellIndex, {\n                letter: word.text[letterIndex],\n                wordIndex,\n                step: letterIndex + 1,\n              });\n            });\n          });\n\n          const totalCells = seed.rows * seed.cols;\n          const cells = Array.from({ length: totalCells }, (_, index) =>\n            occupied.has(index)\n              ? { type: \"tile\", ...occupied.get(index) }\n              : { type: \"block\" }\n          );\n\n          return {\n            ...seed,\n            cells,\n            playableCount: occupied.size,\n          };\n        });\n      }\n\n      function toCoord(index, cols) {\n        return [Math.floor(index / cols), index % cols];\n      }\n\n      const puzzles = hydratePuzzles();\n\n      function puzzlesForSelectedSize() {\n        return puzzles.filter(\n          (puzzle) => `${puzzle.rows}x${puzzle.cols}` === state.selectedGridSize\n        );\n      }\n\n      function storageKeyFor(puzzle) {\n        return `wordfinder:${puzzle.id}`;\n      }\n\n      function saveState() {\n        const payload = {\n          foundWords: state.foundWords,\n          hints: state.hints,\n          startTime: state.startTime,\n        };\n        localStorage.setItem(storageKeyFor(state.puzzle), JSON.stringify(payload));\n      }\n\n      function loadStateForPuzzle(puzzle) {\n        try {\n          const raw = localStorage.getItem(storageKeyFor(puzzle));\n          if (!raw) return null;\n          return JSON.parse(raw);\n        } catch {\n          return null;\n        }\n      }\n\n      function getDailyPuzzle() {\n        const day = Math.floor(Date.now() / 86400000);\n        const filtered = puzzlesForSelectedSize();\n        return filtered[day % filtered.length];\n      }\n\n      function startPuzzle(puzzle, mode) {\n        state.mode = mode;\n        state.puzzle = puzzle;\n        state.activePath = [];\n        state.invalidTiles = [];\n        state.gestureExtended = false;\n        state.draggingPointerId = null;\n        state.message = \"Trace a word path. Every playable tile must end up in exactly one answer.\";\n        const saved = loadStateForPuzzle(puzzle);\n        state.foundWords = saved?.foundWords || [];\n        state.hints = saved?.hints || {};\n        state.startTime = saved?.startTime || Date.now();\n        ensureTimer();\n        render();\n      }\n\n      function ensureTimer() {\n        if (state.timerHandle) {\n          clearInterval(state.timerHandle);\n        }\n        updateTimer();\n        state.timerHandle = setInterval(updateTimer, 1000);\n      }\n\n      function updateTimer() {\n        const elapsedSeconds = Math.floor((Date.now() - state.startTime) / 1000);\n        const minutes = String(Math.floor(elapsedSeconds / 60)).padStart(2, \"0\");\n        const seconds = String(elapsedSeconds % 60).padStart(2, \"0\");\n        els.timer.textContent = `${minutes}:${seconds}`;\n      }\n\n      function activeWordPath() {\n        return state.activePath.map((index) => state.puzzle.cells[index].letter).join(\"\");\n      }\n\n      function isSolvedWord(wordIndex) {\n        return state.foundWords.includes(wordIndex);\n      }\n\n      function isLockedTile(index) {\n        const cell = state.puzzle.cells[index];\n        return cell.type === \"tile\" && isSolvedWord(cell.wordIndex);\n      }\n\n      function isAdjacent(a, b) {\n        const [r1, c1] = toCoord(a, state.puzzle.cols);\n        const [r2, c2] = toCoord(b, state.puzzle.cols);\n        return Math.abs(r1 - r2) + Math.abs(c1 - c2) === 1;\n      }\n\n      function setMessage(text) {\n        state.message = text;\n        renderMessage();\n      }\n\n      function renderMessage() {\n        els.currentPath.textContent = activeWordPath() || \"—\";\n        els.messageText.textContent = state.message;\n      }\n\n      function revealHint() {\n        const nextWordIndex = state.puzzle.words.findIndex((_, index) => !isSolvedWord(index));\n        if (nextWordIndex === -1) return;\n\n        const revealed = state.hints[nextWordIndex] || 0;\n        state.hints[nextWordIndex] = Math.min(\n          state.puzzle.words[nextWordIndex].text.length,\n          revealed + 1\n        );\n        saveState();\n        setMessage(\n          `Hint revealed for ${\n            state.puzzle.words[nextWordIndex].text.length\n          }-letter word. Follow the glowing tile.`\n        );\n        render();\n      }\n\n      function resetProgress() {\n        state.activePath = [];\n        state.foundWords = [];\n        state.hints = {};\n        state.invalidTiles = [];\n        state.startTime = Date.now();\n        saveState();\n        setMessage(\"Board reset. Start from any open tile.\");\n        render();\n      }\n\n      function undoPath() {\n        if (state.activePath.length > 0) {\n          state.activePath.pop();\n          setMessage(\"Last step removed.\");\n          render();\n        }\n      }\n\n      function clearInvalidTiles() {\n        if (state.invalidTiles.length === 0) return;\n        state.invalidTiles = [];\n        render();\n      }\n\n      function submitPath() {\n        if (state.activePath.length === 0) {\n          setMessage(\"Start a path before submitting.\");\n          return;\n        }\n\n        const matchedWordIndex = state.puzzle.words.findIndex((word, index) => {\n          if (isSolvedWord(index)) return false;\n          if (word.path.length !== state.activePath.length) return false;\n          return word.path.every((cellIndex, pathIndex) => cellIndex === state.activePath[pathIndex]);\n        });\n\n        if (matchedWordIndex === -1) {\n          state.invalidTiles = [...state.activePath];\n          state.activePath = [];\n          setMessage(\"Not one of the hidden answer paths. Try a different partition.\");\n          render();\n          window.setTimeout(clearInvalidTiles, 420);\n          return;\n        }\n\n        state.foundWords = [...state.foundWords, matchedWordIndex].sort((a, b) => a - b);\n        state.activePath = [];\n        saveState();\n\n        if (state.foundWords.length === state.puzzle.words.length) {\n          setMessage(\"Solved. Every playable tile is accounted for.\");\n        } else {\n          const remaining = state.puzzle.words.length - state.foundWords.length;\n          setMessage(`Correct. ${remaining} word${remaining === 1 ? \"\" : \"s\"} left.`);\n        }\n\n        render();\n      }\n\n      function extendPath(index) {\n        const cell = state.puzzle.cells[index];\n        if (!cell || cell.type !== \"tile\" || isLockedTile(index)) return;\n\n        const last = state.activePath[state.activePath.length - 1];\n        const previous = state.activePath[state.activePath.length - 2];\n\n        if (last === index) return;\n\n        if (previous === index) {\n          state.activePath.pop();\n          state.gestureExtended = true;\n          renderMessage();\n          renderBoard();\n          return;\n        }\n\n        if (state.activePath.includes(index)) return;\n\n        if (last !== undefined && !isAdjacent(last, index)) return;\n\n        state.activePath.push(index);\n        if (last !== undefined) {\n          state.gestureExtended = true;\n        }\n        renderMessage();\n        renderBoard();\n      }\n\n      function beginPath(index, pointerId = null) {\n        clearInvalidTiles();\n        if (state.activePath.length === 0) {\n          state.activePath = [index];\n        } else {\n          extendPath(index);\n        }\n        state.draggingPointerId = pointerId;\n        state.gestureExtended = false;\n        setMessage(\"Build a path through neighboring tiles, then release or submit.\");\n        render();\n      }\n\n      function handlePointerDown(index, event) {\n        const cell = state.puzzle.cells[index];\n        if (!cell || cell.type !== \"tile\" || isLockedTile(index)) return;\n        beginPath(index, event.pointerId);\n      }\n\n      function handlePointerEnter(index, event) {\n        if (state.draggingPointerId !== event.pointerId) return;\n        extendPath(index);\n      }\n\n      function handlePointerUp(event) {\n        if (state.draggingPointerId !== event.pointerId) return;\n        if (state.gestureExtended && state.activePath.length > 0) {\n          submitPath();\n        }\n        state.draggingPointerId = null;\n        state.gestureExtended = false;\n      }\n\n      function handleTileClick(index) {\n        const cell = state.puzzle.cells[index];\n        if (!cell || cell.type !== \"tile\" || isLockedTile(index)) return;\n\n        if (state.activePath.length === 0) {\n          state.activePath = [index];\n          setMessage(\"Tap adjacent tiles to build a path, then submit.\");\n        } else {\n          extendPath(index);\n        }\n        render();\n      }\n\n      function renderBoard() {\n        els.board.style.gridTemplateColumns = `repeat(${state.puzzle.cols}, minmax(0, 1fr))`;\n        els.board.innerHTML = \"\";\n\n        state.puzzle.cells.forEach((cell, index) => {\n          if (cell.type === \"block\") {\n            const block = document.createElement(\"div\");\n            block.className = \"block\";\n            els.board.appendChild(block);\n            return;\n          }\n\n          const button = document.createElement(\"button\");\n          button.type = \"button\";\n          button.className = \"tile\";\n          button.textContent = cell.letter;\n          button.setAttribute(\"aria-label\", `Letter ${cell.letter}`);\n\n          if (state.activePath.includes(index)) button.classList.add(\"active\");\n          if (isSolvedWord(cell.wordIndex)) button.classList.add(\"found\", \"locked\");\n          if (state.invalidTiles.includes(index)) button.classList.add(\"invalid\");\n          if ((state.hints[cell.wordIndex] || 0) >= cell.step) button.classList.add(\"hinted\");\n\n          const hintBadge = document.createElement(\"span\");\n          hintBadge.className = \"tile-index\";\n          if ((state.hints[cell.wordIndex] || 0) >= cell.step && !isSolvedWord(cell.wordIndex)) {\n            hintBadge.textContent = cell.step;\n          }\n          button.appendChild(hintBadge);\n\n          button.addEventListener(\"pointerdown\", (event) => handlePointerDown(index, event));\n          button.addEventListener(\"pointerenter\", (event) => handlePointerEnter(index, event));\n          button.addEventListener(\"pointerup\", handlePointerUp);\n          button.addEventListener(\"click\", () => handleTileClick(index));\n\n          els.board.appendChild(button);\n        });\n      }\n\n      function hintedDisplay(word, wordIndex) {\n        const count = state.hints[wordIndex] || 0;\n        return word.text\n          .split(\"\")\n          .map((letter, index) => (index < count ? letter : \"•\"))\n          .join(\" \");\n      }\n\n      function renderSlots() {\n        els.slots.innerHTML = \"\";\n\n        state.puzzle.words.forEach((word, index) => {\n          const solved = isSolvedWord(index);\n          const slot = document.createElement(\"div\");\n          slot.className = `slot${solved ? \" solved\" : \"\"}`;\n\n          const header = document.createElement(\"div\");\n          header.className = \"slot-header\";\n\n          const label = document.createElement(\"span\");\n          label.className = \"slot-title\";\n          label.textContent = `${word.text.length} letters`;\n\n          const stateText = document.createElement(\"span\");\n          stateText.className = \"slot-title\";\n          stateText.textContent = solved ? \"Solved\" : \"Hidden\";\n\n          header.append(label, stateText);\n\n          const value = document.createElement(\"div\");\n          value.className = \"slot-value\";\n          value.textContent = solved ? word.text.split(\"\").join(\" \") : hintedDisplay(word, index);\n\n          slot.append(header, value);\n          els.slots.appendChild(slot);\n        });\n      }\n\n      function renderSummary() {\n        els.modePill.textContent = state.mode === \"daily\" ? \"Daily puzzle\" : \"Practice puzzle\";\n        els.puzzlePill.textContent = `${state.puzzle.name} • ${state.puzzle.rows}x${state.puzzle.cols}`;\n        els.foundCount.textContent = `${state.foundWords.length} / ${state.puzzle.words.length}`;\n        els.hintCount.textContent = String(\n          Object.values(state.hints).reduce((sum, value) => sum + value, 0)\n        );\n        els.gridSize.value = state.selectedGridSize;\n\n        const solved = state.foundWords.length === state.puzzle.words.length;\n        els.successBanner.hidden = !solved;\n        if (solved) {\n          els.successText.textContent = `Solved in ${els.timer.textContent} with ${els.hintCount.textContent} hint(s).`;\n        }\n      }\n\n      function render() {\n        renderBoard();\n        renderSlots();\n        renderSummary();\n        renderMessage();\n      }\n\n      function nextPracticePuzzle() {\n        const filtered = puzzlesForSelectedSize();\n        state.practiceIndex = (state.practiceIndex + 1) % filtered.length;\n        startPuzzle(filtered[state.practiceIndex], \"practice\");\n      }\n\n      function applyGridSize(value) {\n        state.selectedGridSize = value;\n        state.practiceIndex = 0;\n        startPuzzle(getDailyPuzzle(), state.mode);\n      }\n\n      els.dailyBtn.addEventListener(\"click\", () => startPuzzle(getDailyPuzzle(), \"daily\"));\n      els.practiceBtn.addEventListener(\"click\", nextPracticePuzzle);\n      els.submitBtn.addEventListener(\"click\", submitPath);\n      els.undoBtn.addEventListener(\"click\", undoPath);\n      els.hintBtn.addEventListener(\"click\", revealHint);\n      els.resetBtn.addEventListener(\"click\", resetProgress);\n      els.gridSize.addEventListener(\"change\", (event) => applyGridSize(event.target.value));\n      window.addEventListener(\"pointerup\", handlePointerUp);\n\n      startPuzzle(getDailyPuzzle(), \"daily\");\n    </script>\n  </body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/favicon.ico") {
      return new Response(null, { status: 204 });
    }

    return new Response(HTML, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store"
      }
    });
  }
};
